453	}
454	
455	// Link
456	.link {
457	  color: $user-primary-400;
458	  text-decoration: none;
459	  transition: color $transition-base;
460	
461	  &:hover {
462	    color: $user-primary-500;
463	    text-decoration: underline;
464	  }
465	}
466	
467	// Utility Classes
468	.text-muted {
469	  color: $user-text-muted;
470	}
471	
472	.text-secondary {
473	  color: $user-text-secondary;
474	}
475	
476	.mono {
477	  @include text-mono;
478	}
