1	@use '../../../../styles/variables' as *;
2	@use '../../../../styles/mixins' as *;
3	
4	// ── Theme ─────────────────────────────────────────────────────
5	$primary:      #059669;
6	$primary-dark: #047857;
7	$primary-bg:   #f0fdf4;
8	$primary-muted:#d1fae5;
9	$border:       #e5e7eb;
10	$surface:      #ffffff;
11	$text:         #064e3b;
12	$text-muted:   #6b7280;
13	$bottom-nav-h: 64px;
14	$app-bar-h:    56px;
15	
16	// ── Host ──────────────────────────────────────────────────────
17	:host {
18	  display: flex;
19	  flex-direction: column;
20	  min-height: 100vh;
21	  background: $primary-bg;
22	  font-family: $font-family-base;
23	  color: $text;
24	}
25	
26	// ── App bar ───────────────────────────────────────────────────
27	.app-bar {
28	  position: sticky;
29	  top: 0;
30	  z-index: $z-sticky;
31	  background: $surface;
32	  border-bottom: 1px solid $border;
33	  box-shadow: 0 1px 4px rgba(0,0,0,0.06);
34	
35	  &__inner {
36	    display: flex;
37	    align-items: center;
38	    justify-content: space-between;
39	    padding: 0 $space-4;
40	    height: $app-bar-h;
41	  }
42	
43	  &__brand { display: flex; align-items: center; gap: $space-2; }
44	  &__logo  { font-size: 1.4rem; color: $primary; }
45	  &__title { font-size: $font-size-lg; font-weight: $font-weight-bold; color: $text; }
46	
47	  &__meta { display: flex; align-items: center; gap: $space-3; }
48	
49	  &__key {
50	    font-size: $font-size-xs;
51	    font-family: $font-family-mono;
52	    color: $text-muted;
53	    background: #f3f4f6;
54	    padding: 2px 8px;
55	    border-radius: $radius-full;
56	    @include truncate;
57	    max-width: 140px;
58	  }
59	
60	  &__refresh {
61	    width: 36px; height: 36px;
62	    background: none; border: none; cursor: pointer;
63	    font-size: 1.2rem; color: $primary;
64	    border-radius: $radius-full;
65	    display: flex; align-items: center; justify-content: center;
66	    transition: background $transition-base;
67	    &:hover { background: $primary-muted; }
68	    &:disabled { opacity: 0.4; cursor: not-allowed; }
69	  }
70	}
71	
72	@keyframes spin { to { transform: rotate(360deg); } }
73	.spinning { display: inline-block; animation: spin 0.8s linear infinite; }
74	
75	// ── Filter bar (desktop) ──────────────────────────────────────
76	.filter-bar {
77	  display: flex;
78	  align-items: flex-end;
79	  flex-wrap: wrap;
80	  gap: $space-2;
81	  padding: $space-3 $space-4;
82	  border-top: 1px solid $border;
83	  background: #fafafa;
84	  overflow-x: auto;
85	
86	  &__field {
87	    display: flex; flex-direction: column; gap: $space-1;
88	  }
89	
