91	    font-size: $font-size-xs; font-weight: $font-weight-semibold;
92	    color: $text-muted; text-transform: uppercase; letter-spacing: 0.04em;
93	  }
94	
95	  &__input {
96	    padding: $space-2 $space-3;
97	    border: 1px solid $border; border-radius: $radius-md;
98	    font-size: $font-size-sm; color: $text;
99	    background: $surface; min-width: 160px;
100	    &:focus { outline: none; border-color: $primary; box-shadow: 0 0 0 3px rgba($primary, 0.1); }
101	    &:disabled {
102	      background: #f0f0f0;
103	      color: $text-muted;
104	      border-color: #ddd;
105	      cursor: not-allowed;
106	      opacity: 0.6;
107	    }
108	  }
109	
110	  &__btn {
111	    padding: $space-2 $space-4;
112	    border-radius: $radius-md; font-size: $font-size-sm;
113	    font-weight: $font-weight-semibold; cursor: pointer;
114	    border: 1px solid $border; background: $surface; color: $text-muted;
115	    transition: all $transition-base; align-self: flex-end;
116	    &:hover { background: #f3f4f6; }
117	    &--primary { background: $primary; color: #fff; border-color: $primary;
118	      &:hover { background: $primary-dark; } }
119	  }
120	
121	  &__actions { display: flex; gap: $space-2; align-self: flex-end; margin-left: auto; }
122	}
123	
124	
125	// ── Desktop tab bar (hidden on mobile) ───────────────────────
126	.desktop-tabs {
127	  display: none;
128	  border-top: 1px solid $border;
129	  padding: 0 $space-4;
130	  background: $surface;
131	
132	  @include md { display: flex; gap: 0; }
133	}
134	
135	.desktop-tab {
136	  padding: $space-3 $space-5;
137	  background: none;
138	  border: none;
139	  border-bottom: 3px solid transparent;
140	  font-size: $font-size-sm;
141	  font-weight: $font-weight-semibold;
142	  color: $text-muted;
143	  cursor: pointer;
144	  transition: color $transition-base, border-color $transition-base;
145	  white-space: nowrap;
146	
147	  &:hover { color: $primary; }
148	
149	  &--active {
150	    color: $primary;
151	    border-bottom-color: $primary;
152	  }
153	}
154	
155	// ── Loading bar ───────────────────────────────────────────────
156	.loading-bar {
157	  height: 3px;
158	  background: linear-gradient(90deg, $primary, lighten($primary, 20%));
159	  animation: loading 1.2s ease infinite;
160	}
161	@keyframes loading {
162	  0%   { transform: translateX(-100%); }
163	  100% { transform: translateX(100%); }
164	}
165	
166	// ── Main content ──────────────────────────────────────────────
167	.main-content {
168	  flex: 1;
169	  padding: $space-4;
170	  padding-bottom: calc(#{$bottom-nav-h} + #{$space-4});
171	
172	  @include md { padding-bottom: $space-4; }
173	}
174	
175	.tab-content { animation: fade-in 0.15s ease; }
176	@keyframes fade-in { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }
177	
178	// ── Desktop table ─────────────────────────────────────────────
179	.table-wrap {
180	  display: none;
181	  overflow-x: auto;
182	  border-radius: $radius-lg;
183	  border: 1px solid $border;
184	  box-shadow: 0 1px 4px rgba(0,0,0,0.04);
185	
186	  @include md { display: block; }
187	}
188	
189	.grid {
190	  width: 100%; border-collapse: collapse; background: $surface;
191	
192	  th, td {
193	    padding: $space-3; text-align: left;
194	    font-size: $font-size-sm; border-bottom: 1px solid $border;
195	  }
196	
197	  th {
198	    background: $primary-bg; color: $primary-dark;
199	    font-weight: $font-weight-semibold; font-size: $font-size-xs;
200	    text-transform: uppercase; letter-spacing: 0.05em;
201	  }
202	
203	  tbody tr {
204	    transition: background $transition-fast; cursor: pointer;
205	    &:hover { background: rgba($primary, 0.04); }
206	    &:last-child td { border-bottom: none; }
207	  }
208	
209	  .selectable-row.selected { background: rgba($primary, 0.1) !important; }
210	}
211	
212	// ── Mobile card list ──────────────────────────────────────────
213	.card-list {
214	  display: flex; flex-direction: column; gap: $space-3;
215	
216	  @include md { display: none; }
217	}
218	
219	.token-card {
220	  background: $surface;
221	  border: 1px solid $border;
222	  border-radius: $radius-xl;
223	  padding: $space-4;
224	  cursor: pointer;
225	  transition: box-shadow $transition-base, transform $transition-base;
226	  -webkit-tap-highlight-color: transparent;
227	
228	  &:active { transform: scale(0.98); }
229	  &:hover  { box-shadow: 0 4px 16px rgba($primary, 0.1); }
230	
231	  &--buyable { border-left: 4px solid $primary; }
232	
233	  &__header {
234	    display: flex; align-items: center;
235	    justify-content: space-between; margin-bottom: $space-3;
236	  }
237	
238	  &__company {
239	    font-size: $font-size-base; font-weight: $font-weight-semibold;
240	    color: $text; @include truncate; max-width: 60%;
241	  }
242	
243	  &__body {
244	    display: grid; grid-template-columns: 1fr 1fr;
245	    gap: $space-2 $space-4; margin-bottom: $space-3;
246	  }
247	
248	  &__stat { display: flex; flex-direction: column; gap: 2px; }
249	
250	  &__stat-label {
251	    font-size: $font-size-xs; font-weight: $font-weight-semibold;
252	    color: $text-muted; text-transform: uppercase; letter-spacing: 0.04em;
253	  }
254	
255	  &__stat-value { font-size: $font-size-sm; color: $text; font-weight: $font-weight-medium; }
256	
257	  &__footer {
258	    display: flex; align-items: center;
259	    justify-content: space-between;
260	    border-top: 1px solid $border; padding-top: $space-2; margin-top: $space-1;
261	  }
262	
263	  &__id { font-size: $font-size-xs; color: $text-muted; font-family: $font-family-mono; }
264	  &__chevron { font-size: 1.2rem; color: $primary; font-weight: $font-weight-bold; }
265	
266	  &__get-service-btn {
267	    padding: 4px 12px;
268	    border-radius: $radius-md;
269	    font-size: $font-size-xs;
270	    font-weight: $font-weight-semibold;
271	    background: $primary;
272	    color: #fff;
273	    border: none;
274	    cursor: pointer;
275	    transition: background $transition-base;
276	    &:hover { background: $primary-dark; }
277	  }
278	}
279	
280	// ── Badges ────────────────────────────────────────────────────
281	.badge {
282	  display: inline-flex; align-items: center;
283	  padding: 2px 10px; border-radius: $radius-full;
284	  font-size: $font-size-xs; font-weight: $font-weight-semibold;
285	
286	  &--green  { background: #dcfce7; color: #166534; }
287	  &--blue   { background: #dbeafe; color: #1e40af; }
288	  &--gray   { background: #f3f4f6; color: #6b7280; }
289	  &--yellow { background: #fef9c3; color: #854d0e; }
290	}
291	
292	// ── Action buttons ────────────────────────────────────────────
293	.action-btn {
294	  padding: $space-2 $space-4; border-radius: $radius-md;
295	  font-size: $font-size-sm; font-weight: $font-weight-semibold;
296	  cursor: pointer; border: none; transition: all $transition-base;
297	
298	  &--green {
299	    background: $primary; color: #fff;
300	    &:hover:not(:disabled) { background: $primary-dark; box-shadow: 0 4px 12px rgba($primary, 0.3); }
301	  }
302	  &--warn {
303	    background: $warning-500; color: #fff;
304	    &:hover:not(:disabled) { background: $warning-600; }
305	  }
306	  &:disabled { opacity: 0.45; cursor: not-allowed; }
307	}
308	
309	// ── Empty / muted ─────────────────────────────────────────────
310	.empty-msg {
311	  text-align: center; color: $text-muted;
312	  font-size: $font-size-sm; padding: $space-8 0;
313	}
314	
315	.mono { font-family: $font-family-mono; font-size: $font-size-xs; }
316	
317	// ── Bottom navigation bar ─────────────────────────────────────
318	.bottom-nav {
319	  position: fixed;
320	  bottom: 0; left: 0; right: 0;
321	  height: $bottom-nav-h;
322	  background: $surface;
323	  border-top: 1px solid $border;
324	  display: flex;
325	  box-shadow: 0 -2px 12px rgba(0,0,0,0.06);
326	  z-index: $z-sticky;
327	  // Safe area for iPhone home bar
328	  padding-bottom: env(safe-area-inset-bottom, 0);
329	
330	  @include md { display: none; }
331	
332	  &__tab {
333	    flex: 1;
334	    display: flex; flex-direction: column;
335	    align-items: center; justify-content: center;
336	    gap: 3px; border: none; background: none;
337	    cursor: pointer; color: $text-muted;
338	    font-size: $font-size-xs; font-weight: $font-weight-medium;
339	    transition: color $transition-base;
340	    -webkit-tap-highlight-color: transparent;
341	    padding: 0;
342	
343	    &--active {
344	      color: $primary;
345	      .bottom-nav__icon { transform: scale(1.15); }
346	    }
347	
348	    &:hover { color: $primary; }
349	  }
350	
351	  &__icon { font-size: 1.3rem; transition: transform $transition-base; }
352	  &__label { font-size: 10px; font-weight: $font-weight-semibold; }
353	}
354	
355	// ── Cart button in tab bar ─────────────────────────────────
356	.desktop-tabs {
357	  &__spacer { flex: 1; }
358	}
359	
360	.cart-btn {
361	  display: flex;
362	  align-items: center;
363	  gap: 6px;
364	  padding: 8px 18px;
365	  background: #059669;
366	  color: #fff;
367	  border: none;
368	  border-radius: $radius-full;
369	  font-size: $font-size-sm;
370	  font-weight: $font-weight-semibold;
371	  cursor: pointer;
372	  transition: background $transition-base;
373	  margin-left: auto;
374	  margin-right: $space-4;
375	  margin-bottom: 6px;
376	  &:hover { background: #047857; }
377	
378	  &__badge {
379	    background: #fff;
380	    color: #059669;
381	    border-radius: $radius-full;
382	    font-size: 0.7rem;
383	    font-weight: 700;
384	    padding: 0 6px;
385	    min-width: 18px;
386	    text-align: center;
387	    line-height: 18px;
388	  }
389	}
390	
391	// ── Logout button ──────────────────────────────────────────
392	.logout-btn {
393	  display: flex;
394	  align-items: center;
395	  gap: 6px;
396	  padding: 6px 16px;
397	  background: #dc2626;
398	  color: #fff;
399	  border: none;
400	  border-radius: $radius-full;
401	  font-size: $font-size-sm;
402	  font-weight: $font-weight-semibold;
403	  cursor: pointer;
404	  transition: background $transition-base, transform $transition-base;
405	  letter-spacing: 0.02em;
406	  box-shadow: 0 2px 8px rgba(220, 38, 38, 0.35);
407	  white-space: nowrap;
408	
409	  &:hover {
410	    background: #b91c1c;
411	    transform: translateY(-1px);
412	    box-shadow: 0 4px 12px rgba(220, 38, 38, 0.45);
413	  }
414	
415	  &:active { transform: translateY(0); }
416	}
417	
418	.cart-badge-mobile {
419	  position: absolute;
420	  top: -4px; right: -4px;
421	  background: #ef4444;
422	  color: #fff;
423	  border-radius: 50%;
424	  font-size: 0.6rem;
425	  font-weight: 700;
426	  width: 16px; height: 16px;
427	  display: flex; align-items: center; justify-content: center;
428	}
429	
430	// ── Card grid ──────────────────────────────────────────────
431	.card-grid {
432	  display: grid;
433	  grid-template-columns: repeat(5, 1fr);
434	  gap: 20px;
435	  padding: $space-4;
436	
437	  @media (max-width: 1400px) { grid-template-columns: repeat(4, 1fr); }
438	  @media (max-width: 1100px) { grid-template-columns: repeat(3, 1fr); }
439	  @media (max-width: 800px)  { grid-template-columns: repeat(2, 1fr); }
440	  @media (max-width: 520px)  { grid-template-columns: 1fr; }
441	}
442	
443	// ── Token card ─────────────────────────────────────────────
444	.token-card {
445	  background: #fff;
446	  border: 1px solid #d1fae5;
447	  border-radius: 16px;
448	  overflow: hidden;
449	  cursor: pointer;
450	  display: flex;
451	  flex-direction: column;
452	  transition: transform 0.18s ease, box-shadow 0.18s ease;
453	
454	  &:hover {
455	    transform: translateY(-4px);
456	    box-shadow: 0 12px 32px rgba(5,150,105,0.15);
457	    border-color: $primary;
458	  }
459	
460	  &--buyable { border-color: #a7f3d0; }
461	
462	  &__image {
463	    height: 200px;
464	    background: #f0fdf4;
465	    display: flex; align-items: center; justify-content: center;
466	    overflow: hidden;
467	    img { width: 100%; height: 100%; object-fit: cover; }
468	  }
469	
470	  &__image-placeholder {
471	    font-size: 3rem; color: #a7f3d0;
472	  }
473	
474	  &__header {
475	    display: flex; align-items: center; justify-content: space-between;
476	    padding: 12px 14px 4px;
477	  }
478	
479	  &__company {
480	    font-size: 0.72rem; font-weight: 700;
481	    color: $primary; text-transform: uppercase; letter-spacing: 0.06em;
482	  }
483	
484	  &__product {
485	    padding: 0 14px 8px;
486	    font-size: 1rem; font-weight: 700; color: #064e3b; line-height: 1.3;
487	  }
488	
489	  &__body {
490	    display: flex; flex-wrap: wrap; gap: 20px 8px;
491	    padding: 4px 14px 16px;
492	    flex: 1;
493	  }
494	
495	  &__stat {
496	    display: flex; flex-direction: column;
497	    font-size: 0.8rem; color: #374151;
498	    min-width: 60px;
499	  }
500	
501	  &__stat-row {
502	    display: flex; flex-basis: 100%; width: 100%;
503	    gap: 16px;
504	    > .token-card__stat { flex: 1; min-width: 0; }
505	  }
506	
507	  &__stat--full {
508	    flex-basis: 100%; width: 100%;
509	  }
510	
511	  &__stat-label {
512	    font-size: 0.66rem; color: #9ca3af;
513	    font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em;
514	  }
515	
516	  &__price { color: $primary; font-weight: 700; }
517	  &__mono  { font-family: $font-family-mono; font-size: 0.75rem; }
518	
519	  &__footer {
520	    display: flex; align-items: center; justify-content: space-between;
521	    padding: 8px 14px 12px;
522	    border-top: 1px solid #f0fdf4;
523	  }
524	
525	  &__id { font-size: 0.7rem; color: $text-muted; font-family: $font-family-mono; }
526	  &__chevron { font-size: 0.8rem; color: $primary; font-weight: 600; }
527	
528	  &__actions {
529	    display: flex; gap: 6px; flex-wrap: wrap;
530	  }
531	}
532	
533	// ── Primary market: don't stretch card body ────────────────
534	.token-card--primary .token-card__body { flex: 0 0 auto; padding-top: 16px; }
535	
536	// ── Primary market: align footer buttons to the right ──────
537	.token-card--primary .token-card__footer {
538	  flex-direction: row;
539	  align-items: center;
540	  padding-right: 6px;
541	  .token-card__actions { margin-left: auto; flex-direction: column; align-items: flex-end; }
542	}
543	
544	// ── Small action buttons on cards ─────────────────────────
545	.tc-btn {
546	  padding: 8px 16px;
547	  border-radius: $radius-md;
548	  font-size: $font-size-sm;
549	  font-weight: $font-weight-semibold;
550	  cursor: pointer;
551	  border: none;
552	  transition: background $transition-base, opacity $transition-base;
553	
554	  &--sm { padding: 4px 10px; font-size: 0.75rem; }
555	
556	  &--green { background: $primary; color: #fff; &:hover { background: $primary-dark; } }
557	  &--outline {
558	    background: transparent; color: $primary;
559	    border: 1.5px solid $primary;
560	    &:hover { background: $primary-muted; }
561	  }
562	  &--in-cart { background: #d1fae5; color: #065f46; border-color: #6ee7b7; }
563	  &--warn { background: #f59e0b; color: #fff; &:hover { background: #d97706; } }
564	  &--ghost { background: transparent; color: $text-muted; &:hover { background: #f3f4f6; } }
565	
566	  &:disabled { opacity: 0.45; cursor: not-allowed; }
567	}
568	
569	// ── Modal backdrop & modal ─────────────────────────────────
570	.modal-backdrop {
571	  position: fixed; inset: 0;
572	  background: rgba(0,0,0,0.45);
573	  display: flex; align-items: center; justify-content: center;
574	  z-index: 1000;
575	  padding: $space-4;
576	  overflow-y: auto;
577	}
578	
579	.modal {
580	  background: #fff;
581	  border-radius: 20px;
582	  width: 100%; max-width: 520px;
583	  max-height: 90vh;
584	  overflow-y: auto;
585	  position: relative;
586	  box-shadow: 0 24px 64px rgba(0,0,0,0.2);
587	
588	  &__close {
589	    position: absolute; top: 14px; right: 14px;
590	    width: 32px; height: 32px;
591	    background: #f3f4f6; border: none; border-radius: 50%;
592	    font-size: 1.1rem; cursor: pointer; color: #374151;
593	    display: flex; align-items: center; justify-content: center;
594	    &:hover { background: #e5e7eb; }
595	  }
596	
597	  &__image {
598	    height: 280px; background: #f0fdf4;
599	    display: flex; align-items: center; justify-content: center;
600	    overflow: hidden; border-radius: 20px 20px 0 0;
601	    img { width: 100%; height: 100%; object-fit: cover; }
602	  }
603	
604	  &__image-placeholder { font-size: 4rem; color: #a7f3d0; }
605	
606	  &__body { padding: 24px 28px 28px; }
607	
608	  &__company-row {
609	    display: flex; align-items: center; justify-content: space-between;
610	    margin-bottom: 4px;
611	  }
612	
613	  &__company {
614	    font-size: 0.72rem; font-weight: 700;
615	    color: $primary; text-transform: uppercase; letter-spacing: 0.06em;
616	  }
617	
618	  &__product {
619	    font-size: 1.4rem; font-weight: 800; color: #064e3b;
620	    margin-bottom: 16px; line-height: 1.2;
621	  }
622	
623	  &__details {
624	    display: grid; grid-template-columns: 1fr 1fr;
625	    gap: 22px 20px; margin-bottom: 28px;
626	    dt { font-size: 0.7rem; color: #9ca3af; text-transform: uppercase; font-weight: 700; letter-spacing: 0.04em; margin-bottom: 4px; }
627	    dd { font-size: 0.92rem; color: #111; font-weight: 500; margin: 0; }
628	    > div.full-span { grid-column: 1 / -1; }
629	  }
630	
631	  &__price { font-size: 1.1rem; font-weight: 800; color: $primary; }
632	
633	  &__actions {
634	    display: flex; flex-wrap: wrap; gap: 10px; padding-top: 4px;
635	  }
636	}
637	
638	// ── Mono utility ───────────────────────────────────────────
639	.mono { font-family: $font-family-mono; font-size: 0.78rem; word-break: break-all; }
640

file.content:
@use '../../../../styles/variables' as *;
@use '../../../../styles/mixins' as *;

// ── Theme ─────────────────────────────────────────────────────
$primary:      #059669;
$primary-dark: #047857;
$primary-bg:   #f0fdf4;
$primary-muted:#d1fae5;
$border:       #e5e7eb;
$surface:      #ffffff;
$text:         #064e3b;
$text-muted:   #6b7280;
$bottom-nav-h: 64px;
$app-bar-h:    56px;

// ── Host ──────────────────────────────────────────────────────
:host {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  background: $primary-bg;
  font-family: $font-family-base;
  color: $text;
}

// ── App bar ───────────────────────────────────────────────────
.app-bar {
  position: sticky;
  top: 0;
  z-index: $z-sticky;
  background: $surface;
  border-bottom: 1px solid $border;
  box-shadow: 0 1px 4px rgba(0,0,0,0.06);

  &__inner {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 $space-4;
    height: $app-bar-h;
  }

  &__brand { display: flex; align-items: center; gap: $space-2; }
  &__logo  { font-size: 1.4rem; color: $primary; }
  &__title { font-size: $font-size-lg; font-weight: $font-weight-bold; color: $text; }

  &__meta { display: flex; align-items: center; gap: $space-3; }

  &__key {
    font-size: $font-size-xs;
    font-family: $font-family-mono;
    color: $text-muted;
    background: #f3f4f6;
    padding: 2px 8px;
    border-radius: $radius-full;
    @include truncate;
    max-width: 140px;
  }

  &__refresh {
    width: 36px; height: 36px;
    background: none; border: none; cursor: pointer;
    font-size: 1.2rem; color: $primary;
    border-radius: $radius-full;
    display: flex; align-items: center; justify-content: center;
    transition: background $transition-base;
    &:hover { background: $primary-muted; }
    &:disabled { opacity: 0.4; cursor: not-allowed; }
  }
}

@keyframes spin { to { transform: rotate(360deg); } }
.spinning { display: inline-block; animation: spin 0.8s linear infinite; }

// ── Filter bar (desktop) ──────────────────────────────────────
.filter-bar {
  display: flex;
  align-items: flex-end;
  flex-wrap: wrap;
  gap: $space-2;
  padding: $space-3 $space-4;
  border-top: 1px solid $border;
  background: #fafafa;
  overflow-x: auto;

  &__field {
    display: flex; flex-direction: column; gap: $space-1;
  }

  &__label {
    font-size: $font-size-xs; font-weight: $font-weight-semibold;
    color: $text-muted; text-transform: uppercase; letter-spacing: 0.04em;
  }

  &__input {
    padding: $space-2 $space-3;
    border: 1px solid $border; border-radius: $radius-md;
    font-size: $font-size-sm; color: $text;
    background: $surface; min-width: 160px;
    &:focus { outline: none; border-color: $primary; box-shadow: 0 0 0 3px rgba($primary, 0.1); }
    &:disabled {
      background: #f0f0f0;
      color: $text-muted;
      border-color: #ddd;
      cursor: not-allowed;
      opacity: 0.6;
    }
  }

  &__btn {
    padding: $space-2 $space-4;
    border-radius: $radius-md; font-size: $font-size-sm;
    font-weight: $font-weight-semibold; cursor: pointer;
    border: 1px solid $border; background: $surface; color: $text-muted;
    transition: all $transition-base; align-self: flex-end;
    &:hover { background: #f3f4f6; }
    &--primary { background: $primary; color: #fff; border-color: $primary;
      &:hover { background: $primary-dark; } }
  }

  &__actions { display: flex; gap: $space-2; align-self: flex-end; margin-left: auto; }
}


// ── Desktop tab bar (hidden on mobile) ───────────────────────
.desktop-tabs {
  display: none;
  border-top: 1px solid $border;
  padding: 0 $space-4;
  background: $surface;

  @include md { display: flex; gap: 0; }
}

.desktop-tab {
  padding: $space-3 $space-5;
  background: none;
  border: none;
  border-bottom: 3px solid transparent;
  font-size: $font-size-sm;
  font-weight: $font-weight-semibold;
  color: $text-muted;
  cursor: pointer;
  transition: color $transition-base, border-color $transition-base;
  white-space: nowrap;

  &:hover { color: $primary; }

  &--active {
    color: $primary;
    border-bottom-color: $primary;
  }
}

// ── Loading bar ───────────────────────────────────────────────
.loading-bar {
  height: 3px;
  background: linear-gradient(90deg, $primary, lighten($primary, 20%));
  animation: loading 1.2s ease infinite;
}
@keyframes loading {
  0%   { transform: translateX(-100%); }
  100% { transform: translateX(100%); }
}

// ── Main content ──────────────────────────────────────────────
.main-content {
  flex: 1;
  padding: $space-4;
  padding-bottom: calc(#{$bottom-nav-h} + #{$space-4});

  @include md { padding-bottom: $space-4; }
}

.tab-content { animation: fade-in 0.15s ease; }
@keyframes fade-in { from { opacity: 0; transform: translateY(4px); } to { opacity: 1; transform: none; } }

// ── Desktop table ─────────────────────────────────────────────
.table-wrap {
  display: none;
  overflow-x: auto;
  border-radius: $radius-lg;
  border: 1px solid $border;
  box-shadow: 0 1px 4px rgba(0,0,0,0.04);

  @include md { display: block; }
}

.grid {
  width: 100%; border-collapse: collapse; background: $surface;

  th, td {
    padding: $space-3; text-align: left;
    font-size: $font-size-sm; border-bottom: 1px solid $border;
  }

  th {
    background: $primary-bg; color: $primary-dark;
    font-weight: $font-weight-semibold; font-size: $font-size-xs;
    text-transform: uppercase; letter-spacing: 0.05em;
  }

  tbody tr {
    transition: background $transition-fast; cursor: pointer;
    &:hover { background: rgba($primary, 0.04); }
    &:last-child td { border-bottom: none; }
  }

  .selectable-row.selected { background: rgba($primary, 0.1) !important; }
}

// ── Mobile card list ──────────────────────────────────────────
.card-list {
  display: flex; flex-direction: column; gap: $space-3;

  @include md { display: none; }
}

.token-card {
  background: $surface;
  border: 1px solid $border;
  border-radius: $radius-xl;
  padding: $space-4;
  cursor: pointer;
  transition: box-shadow $transition-base, transform $transition-base;
  -webkit-tap-highlight-color: transparent;

  &:active { transform: scale(0.98); }
  &:hover  { box-shadow: 0 4px 16px rgba($primary, 0.1); }

  &--buyable { border-left: 4px solid $primary; }

  &__header {
    display: flex; align-items: center;
    justify-content: space-between; margin-bottom: $space-3;
  }

  &__company {
    font-size: $font-size-base; font-weight: $font-weight-semibold;
    color: $text; @include truncate; max-width: 60%;
  }

  &__body {
    display: grid; grid-template-columns: 1fr 1fr;
    gap: $space-2 $space-4; margin-bottom: $space-3;
  }

  &__stat { display: flex; flex-direction: column; gap: 2px; }

  &__stat-label {
    font-size: $font-size-xs; font-weight: $font-weight-semibold;
    color: $text-muted; text-transform: uppercase; letter-spacing: 0.04em;
  }

  &__stat-value { font-size: $font-size-sm; color: $text; font-weight: $font-weight-medium; }

  &__footer {
    display: flex; align-items: center;
    justify-content: space-between;
    border-top: 1px solid $border; padding-top: $space-2; margin-top: $space-1;
  }

  &__id { font-size: $font-size-xs; color: $text-muted; font-family: $font-family-mono; }
  &__chevron { font-size: 1.2rem; color: $primary; font-weight: $font-weight-bold; }

  &__get-service-btn {
    padding: 4px 12px;
    border-radius: $radius-md;
    font-size: $font-size-xs;
    font-weight: $font-weight-semibold;
    background: $primary;
    color: #fff;
    border: none;
    cursor: pointer;
    transition: background $transition-base;
    &:hover { background: $primary-dark; }
  }
}

// ── Badges ────────────────────────────────────────────────────
.badge {
  display: inline-flex; align-items: center;
  padding: 2px 10px; border-radius: $radius-full;
  font-size: $font-size-xs; font-weight: $font-weight-semibold;

  &--green  { background: #dcfce7; color: #166534; }
  &--blue   { background: #dbeafe; color: #1e40af; }
  &--gray   { background: #f3f4f6; color: #6b7280; }
  &--yellow { background: #fef9c3; color: #854d0e; }
}

// ── Action buttons ────────────────────────────────────────────
.action-btn {
  padding: $space-2 $space-4; border-radius: $radius-md;
  font-size: $font-size-sm; font-weight: $font-weight-semibold;
  cursor: pointer; border: none; transition: all $transition-base;

  &--green {
    background: $primary; color: #fff;
    &:hover:not(:disabled) { background: $primary-dark; box-shadow: 0 4px 12px rgba($primary, 0.3); }
  }
  &--warn {
    background: $warning-500; color: #fff;
    &:hover:not(:disabled) { background: $warning-600; }
  }
  &:disabled { opacity: 0.45; cursor: not-allowed; }
}

// ── Empty / muted ─────────────────────────────────────────────
.empty-msg {
  text-align: center; color: $text-muted;
  font-size: $font-size-sm; padding: $space-8 0;
}

.mono { font-family: $font-family-mono; font-size: $font-size-xs; }

// ── Bottom navigation bar ─────────────────────────────────────
.bottom-nav {
  position: fixed;
  bottom: 0; left: 0; right: 0;
  height: $bottom-nav-h;
  background: $surface;
  border-top: 1px solid $border;
  display: flex;
  box-shadow: 0 -2px 12px rgba(0,0,0,0.06);
  z-index: $z-sticky;
  // Safe area for iPhone home bar
  padding-bottom: env(safe-area-inset-bottom, 0);

  @include md { display: none; }

  &__tab {
    flex: 1;
    display: flex; flex-direction: column;
    align-items: center; justify-content: center;
    gap: 3px; border: none; background: none;
    cursor: pointer; color: $text-muted;
    font-size: $font-size-xs; font-weight: $font-weight-medium;
    transition: color $transition-base;
    -webkit-tap-highlight-color: transparent;
    padding: 0;

    &--active {
      color: $primary;
      .bottom-nav__icon { transform: scale(1.15); }
    }

    &:hover { color: $primary; }
  }

  &__icon { font-size: 1.3rem; transition: transform $transition-base; }
  &__label { font-size: 10px; font-weight: $font-weight-semibold; }
}

// ── Cart button in tab bar ─────────────────────────────────
.desktop-tabs {
  &__spacer { flex: 1; }
}

.cart-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 18px;
  background: #059669;
  color: #fff;
  border: none;
  border-radius: $radius-full;
  font-size: $font-size-sm;
  font-weight: $font-weight-semibold;
  cursor: pointer;
  transition: background $transition-base;
  margin-left: auto;
  margin-right: $space-4;
  margin-bottom: 6px;
  &:hover { background: #047857; }

  &__badge {
    background: #fff;
    color: #059669;
    border-radius: $radius-full;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 0 6px;
    min-width: 18px;
    text-align: center;
    line-height: 18px;
  }
}

// ── Logout button ──────────────────────────────────────────
.logout-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 16px;
  background: #dc2626;
  color: #fff;
  border: none;
  border-radius: $radius-full;
  font-size: $font-size-sm;
  font-weight: $font-weight-semibold;
  cursor: pointer;
  transition: background $transition-base, transform $transition-base;
  letter-spacing: 0.02em;
  box-shadow: 0 2px 8px rgba(220, 38, 38, 0.35);
  white-space: nowrap;

  &:hover {
    background: #b91c1c;
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(220, 38, 38, 0.45);
  }

  &:active { transform: translateY(0); }
}

.cart-badge-mobile {
  position: absolute;
  top: -4px; right: -4px;
  background: #ef4444;
  color: #fff;
  border-radius: 50%;
  font-size: 0.6rem;
  font-weight: 700;
  width: 16px; height: 16px;
  display: flex; align-items: center; justify-content: center;
}

// ── Card grid ──────────────────────────────────────────────
.card-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 20px;
  padding: $space-4;

  @media (max-width: 1400px) { grid-template-columns: repeat(4, 1fr); }
  @media (max-width: 1100px) { grid-template-columns: repeat(3, 1fr); }
  @media (max-width: 800px)  { grid-template-columns: repeat(2, 1fr); }
  @media (max-width: 520px)  { grid-template-columns: 1fr; }
}

// ── Token card ─────────────────────────────────────────────
.token-card {
  background: #fff;
  border: 1px solid #d1fae5;
  border-radius: 16px;
  overflow: hidden;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  transition: transform 0.18s ease, box-shadow 0.18s ease;

  &:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 32px rgba(5,150,105,0.15);
    border-color: $primary;
  }

  &--buyable { border-color: #a7f3d0; }

  &__image {
    height: 200px;
    background: #f0fdf4;
    display: flex; align-items: center; justify-content: center;
    overflow: hidden;
    img { width: 100%; height: 100%; object-fit: cover; }
  }

  &__image-placeholder {
    font-size: 3rem; color: #a7f3d0;
  }

  &__header {
    display: flex; align-items: center; justify-content: space-between;
    padding: 12px 14px 4px;
  }

  &__company {
    font-size: 0.72rem; font-weight: 700;
    color: $primary; text-transform: uppercase; letter-spacing: 0.06em;
  }

  &__product {
    padding: 0 14px 8px;
    font-size: 1rem; font-weight: 700; color: #064e3b; line-height: 1.3;
  }

  &__body {
    display: flex; flex-wrap: wrap; gap: 20px 8px;
    padding: 4px 14px 16px;
    flex: 1;
  }

  &__stat {
    display: flex; flex-direction: column;
    font-size: 0.8rem; color: #374151;
    min-width: 60px;
  }

  &__stat-row {
    display: flex; flex-basis: 100%; width: 100%;
    gap: 16px;
    > .token-card__stat { flex: 1; min-width: 0; }
  }

  &__stat--full {
    flex-basis: 100%; width: 100%;
  }

  &__stat-label {
    font-size: 0.66rem; color: #9ca3af;
    font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em;
  }

  &__price { color: $primary; font-weight: 700; }
  &__mono  { font-family: $font-family-mono; font-size: 0.75rem; }

  &__footer {
    display: flex; align-items: center; justify-content: space-between;
    padding: 8px 14px 12px;
    border-top: 1px solid #f0fdf4;
  }

  &__id { font-size: 0.7rem; color: $text-muted; font-family: $font-family-mono; }
  &__chevron { font-size: 0.8rem; color: $primary; font-weight: 600; }

  &__actions {
    display: flex; gap: 6px; flex-wrap: wrap;
  }
}

// ── Primary market: don't stretch card body ────────────────
.token-card--primary .token-card__body { flex: 0 0 auto; padding-top: 16px; }

// ── Primary market: align footer buttons to the right ──────
.token-card--primary .token-card__footer {
  flex-direction: row;
  align-items: center;
  padding-right: 6px;
  .token-card__actions { margin-left: auto; flex-direction: column; align-items: flex-end; }
}

// ── Small action buttons on cards ─────────────────────────
.tc-btn {
  padding: 8px 16px;
  border-radius: $radius-md;
  font-size: $font-size-sm;
  font-weight: $font-weight-semibold;
  cursor: pointer;
  border: none;
  transition: background $transition-base, opacity $transition-base;

  &--sm { padding: 4px 10px; font-size: 0.75rem; }

  &--green { background: $primary; color: #fff; &:hover { background: $primary-dark; } }
  &--outline {
    background: transparent; color: $primary;
    border: 1.5px solid $primary;
    &:hover { background: $primary-muted; }
  }
  &--in-cart { background: #d1fae5; color: #065f46; border-color: #6ee7b7; }
  &--warn { background: #f59e0b; color: #fff; &:hover { background: #d97706; } }
  &--ghost { background: transparent; color: $text-muted; &:hover { background: #f3f4f6; } }

  &:disabled { opacity: 0.45; cursor: not-allowed; }
}

// ── Modal backdrop & modal ─────────────────────────────────
.modal-backdrop {
  position: fixed; inset: 0;
  background: rgba(0,0,0,0.45);
  display: flex; align-items: center; justify-content: center;
  z-index: 1000;
  padding: $space-4;
  overflow-y: auto;
}

.modal {
  background: #fff;
  border-radius: 20px;
  width: 100%; max-width: 520px;
  max-height: 90vh;
  overflow-y: auto;
  position: relative;
  box-shadow: 0 24px 64px rgba(0,0,0,0.2);

  &__close {
    position: absolute; top: 14px; right: 14px;
    width: 32px; height: 32px;
    background: #f3f4f6; border: none; border-radius: 50%;
    font-size: 1.1rem; cursor: pointer; color: #374151;
    display: flex; align-items: center; justify-content: center;
    &:hover { background: #e5e7eb; }
  }

  &__image {
    height: 280px; background: #f0fdf4;
    display: flex; align-items: center; justify-content: center;
    overflow: hidden; border-radius: 20px 20px 0 0;
    img { width: 100%; height: 100%; object-fit: cover; }
  }

  &__image-placeholder { font-size: 4rem; color: #a7f3d0; }

  &__body { padding: 24px 28px 28px; }

  &__company-row {
    display: flex; align-items: center; justify-content: space-between;
    margin-bottom: 4px;
  }

  &__company {
    font-size: 0.72rem; font-weight: 700;
    color: $primary; text-transform: uppercase; letter-spacing: 0.06em;
  }

  &__product {
    font-size: 1.4rem; font-weight: 800; color: #064e3b;
    margin-bottom: 16px; line-height: 1.2;
  }

  &__details {
    display: grid; grid-template-columns: 1fr 1fr;
    gap: 22px 20px; margin-bottom: 28px;
    dt { font-size: 0.7rem; color: #9ca3af; text-transform: uppercase; font-weight: 700; letter-spacing: 0.04em; margin-bottom: 4px; }
    dd { font-size: 0.92rem; color: #111; font-weight: 500; margin: 0; }
    > div.full-span { grid-column: 1 / -1; }
  }

  &__price { font-size: 1.1rem; font-weight: 800; color: $primary; }

  &__actions {
    display: flex; flex-wrap: wrap; gap: 10px; padding-top: 4px;
  }
}

// ── Mono utility ───────────────────────────────────────────
.mono { font-family: $font-family-mono; font-size: 0.78rem; word-break: break-all; }

